// Puzzle manifest validator. PURE — imports nothing, throws nothing.
//
// The manifest (`puzzles/index.json`) is the list the select screen reads. It is
// GENERATED by `studio/storage/puzzle-store.js` and committed, so a bad one is
// unlikely — but it is also the one file a human is invited to hand-edit, since
// the array order is the play order. That is exactly the file worth checking at
// the boundary.
//
// It validates the SHAPE of the list, never the boards themselves: whether
// `first-light.json` exists and is a valid puzzle is `validatePuzzle`'s job at
// the moment that board is loaded. Two checks, two moments, no overlap.
//
// Returns { ok, errors: [{ path, message }] } and collects EVERY problem — the
// same contract as validate-puzzle.js, so callers handle both identically.

const VERSION = 1;

// Lowercase, hyphen-separated, no leading hyphen. Duplicated from studio/slug.js
// on purpose: this module imports nothing, and the pattern is the boundary
// between a query string and a filesystem path. A shared import would make the
// game's boundary check depend on the Studio.
const SLUG = /^[a-z0-9][a-z0-9-]{0,63}$/;

export function validateManifest(manifest) {
  const errors = [];
  const fail = (path, message) => errors.push({ path, message });

  if (!isObject(manifest)) {
    fail('', 'A puzzle manifest must be a JSON object.');
    return { ok: false, errors };
  }

  if (manifest.schemaVersion !== VERSION) {
    fail(
      'schemaVersion',
      `Required: schemaVersion ${VERSION}; found ${JSON.stringify(manifest.schemaVersion)}.`
    );
  }

  if (!Array.isArray(manifest.puzzles)) {
    fail('puzzles', 'Required: an array of puzzle entries.');
    return { ok: false, errors };
  }

  const seenSlugs = new Set();
  const seenIds = new Set();

  manifest.puzzles.forEach((entry, i) => {
    const at = `puzzles[${i}]`;
    if (!isObject(entry)) {
      fail(at, 'Each entry must be an object.');
      return;
    }

    // The slug becomes a filename and a `?puzzle=` value, so it is pattern-matched
    // rather than merely required — this is the check that makes path traversal
    // impossible by construction downstream.
    if (!isText(entry.slug) || !SLUG.test(entry.slug)) {
      fail(
        `${at}.slug`,
        'Required: lowercase letters, digits and hyphens, starting with a letter or digit.'
      );
    } else if (seenSlugs.has(entry.slug)) {
      fail(`${at}.slug`, `Duplicate slug "${entry.slug}" — a board must appear in the list once.`);
    } else {
      seenSlugs.add(entry.slug);
    }

    if (!isText(entry.id)) fail(`${at}.id`, 'Required: a non-empty string id.');
    else if (seenIds.has(entry.id)) {
      fail(`${at}.id`, `Duplicate id "${entry.id}" — saved results are keyed per board.`);
    } else seenIds.add(entry.id);

    if (!isText(entry.title)) fail(`${at}.title`, 'Required: a non-empty string title.');
  });

  return { ok: errors.length === 0, errors };
}

const isObject = (value) => typeof value === 'object' && value !== null && !Array.isArray(value);
const isText = (value) => typeof value === 'string' && value.trim().length > 0;
